import{_ as o,C as a,o as d,c as n,E as r,a2 as c}from"./chunks/framework.Cm6XCzck.js";const P=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.5","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.5","outline":"deep"},"headers":[],"relativePath":"zh/publications/implementation-case-i0.5/part-01.md","filePath":"zh/publications/implementation-case-i0.5/part-01.md","lastUpdated":1785926126000}'),i={name:"zh/publications/implementation-case-i0.5/part-01.md"};function s(l,e,p,h,u,m){const t=a("ArticleCover");return d(),n("div",null,[r(t,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"S0.4 工程基线，以及 WP-13 多 Agent 证据门控与事实复核案例。",version:"I0.5",status:"S0.4 工程证据草稿",languageHref:"/en/publications/implementation-case-i0.5",languageLabel:"English"}),e[0]||(e[0]=c(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="s0-4-reference-reader、fcop、codeflowmu-与-wp-13-多-agent-事实复核" tabindex="-1">S0.4 Reference Reader、FCoP、CodeFlowMu 与 WP-13 多 Agent 事实复核 <a class="header-anchor" href="#s0-4-reference-reader、fcop、codeflowmu-与-wp-13-多-agent-事实复核" aria-label="Permalink to &quot;S0.4 Reference Reader、FCoP、CodeFlowMu 与 WP-13 多 Agent 事实复核&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> Draft I0.5<br><strong>状态：</strong> 作者生成的实施与案例报告<br><strong>规范目标：</strong> TMPA Core S0.4<br><strong>历史证据基线：</strong> I0.3 / S0.3 语料库<br><strong>报告与执行日期：</strong> 2026-08-03；WP-13 案例观察日期 2026-08-05<br><strong>一致性语料库：</strong> <code>tmpa-s0.4-fcop-codeflowmu-20260803</code><br><strong>权威边界：</strong> 本报告只提供工程证据，不具有规范性；TMPA Core 要求仅由 GitHub Core Specification 定义。</p></blockquote><h1 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h1><p>本报告把 Implementation Case 从一个未进入 GitHub 的 S0.3 时代本地归档，推进为公开、可执行的 S0.4 语料库。I0.5 保留 I0.4 的 Reference Reader、C01–C14 Fixture、Manifest、结果 Envelope、产品证据断言与单命令 Runner，并新增 WP-13 现场案例：当子执行产生带有“完成”意味但缺乏退出状态、测试、Commit 与正式 REPORT 的声明时，PM 根据持久事实不予放行；DEV 恢复后在原任务补齐交付，再由角色分离的 QA 验证。</p><p>FCoP 协议定义项目可见的协调 Profile：路由文本工件、生命周期路径、原子 Rename、只增迁移证据、角色绑定、复核、ISSUE、告警和检查报告都保存在临时模型 Session 之外；其参考实现为这些规则提供有界的可执行证据。CodeFlowMu 作为下游应用采用该协议，用于持久工作身份、任务—报告流、复核门禁、依赖等待、恢复和归档历史。小典 AI 提供来自受治理 NL2SQL Pipeline 的前规范现场证据，包括被保留的通过路径和拒绝路径。</p><p>S0.4 Reference Reader 针对作者生成的合成 Fixture 套件得到 <strong>14 PASS</strong>。单独求值的 FCoP–CodeFlowMu 产品基线仍为 <strong>1 PASS、9 PARTIAL、4 NOT RUN、0 FAIL</strong>，聚合裁决为 <code>PARTIAL</code>。WP-13 增强了 C04、C06、C07 与 C13 相关行为的作者生成 <code>demonstrated</code> 证据，但没有执行新的 S0.4 产品 Reader 标准，因此不改写上述裁决，也不建立独立验证。</p><h1 id="_1-范围与证据边界" tabindex="-1">1. 范围与证据边界 <a class="header-anchor" href="#_1-范围与证据边界" aria-label="Permalink to &quot;1. 范围与证据边界&quot;">​</a></h1><p>本报告回答：S0.4 Reference Reader 实现了什么；锁定产品证据实际演示了什么；哪些 S0.4 产品要求仍未执行。本报告只提供工程证据且不具有规范性，其裁决保留在历史 S0.4 目标下；当前要求与规范测试名称由 <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.5">TMPA Core Specification S0.5</a> 定义，I0.5 不声明 S0.5 一致性。理论由 <a href="/joinwell52/zh/publications/tmpa-architecture-paper-a0.5">Architecture Paper A0.5</a> 解释。</p><p>证据仍分为 <code>specified</code>、<code>implemented</code>、<code>demonstrated</code> 与 <code>independently adopted</code>。Reference Reader 已实现并由作者演示；产品基线包含混合的 implemented/demonstrated 证据，聚合仍为 <code>PARTIAL</code>。Fixture 成功不得转换为 FCoP 或 CodeFlowMu 产品一致性，也不建立独立采用或独立验证。</p><h1 id="_2-工程谱系与组件边界" tabindex="-1">2. 工程谱系与组件边界 <a class="header-anchor" href="#_2-工程谱系与组件边界" aria-label="Permalink to &quot;2. 工程谱系与组件边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前概念分层</span></span>
<span class="line"><span>TMPA 架构 → 可复用 FCoP 协议 Profile → CodeFlowMu 与其他下游应用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>历史谱系</span></span>
<span class="line"><span>小典 AI 实践 → 原始 TMPA → FCoP 抽取与成熟</span></span>
<span class="line"><span>              → CodeFlowMu 应用 → 当前 TMPA 形式化</span></span></code></pre></div><p>FCoP 定义覆盖 TMPA 部分文件型语义的协议 Profile；<code>fcop</code> 与 <code>fcop-mcp</code> Package 是其参考实现，CodeFlowMu 是把该协议作为协调与治理基础设施采用的下游应用。FCoP 不穷尽 TMPA；CodeFlowMu 不定义 FCoP；小典 AI 是谱系和现场证据，不是产品级 TMPA Reader。</p><p>术语遵循 Core Specification 第 2 节：<strong>治理对象</strong>是语义单元，<strong>来源工件</strong>是物理观测，<strong>治理 Reader</strong>是确定性重建阶段，<code>valid</code> / <code>invalid</code> / <code>undetermined</code> 是仅有的三个治理语义判断。本报告不引入替代含义。</p><h1 id="_3-fcop-协议与参考实现证据" tabindex="-1">3. FCoP 协议与参考实现证据 <a class="header-anchor" href="#_3-fcop-协议与参考实现证据" aria-label="Permalink to &quot;3. FCoP 协议与参考实现证据&quot;">​</a></h1><h2 id="_3-1-持久文本消息与状态表面" tabindex="-1">3.1 持久文本消息与状态表面 <a class="header-anchor" href="#_3-1-持久文本消息与状态表面" aria-label="Permalink to &quot;3.1 持久文本消息与状态表面&quot;">​</a></h2><p>FCoP 把项目文件系统作为持久文本消息与状态表面：<strong>文件承载协议，路径表达状态，事件回放迁移。</strong> <code>TASK-*</code> 工件作为稳定工作锚点；报告、复核、ISSUE、告警与决策保持独立；文件名携带路由；生命周期目录暴露状态；原子 Rename 执行迁移；迁移证据说明状态如何到达；工件在 Session 结束后仍可检查。</p><h2 id="_3-2-agent-可见角色绑定" tabindex="-1">3.2 Agent 可见角色绑定 <a class="header-anchor" href="#_3-2-agent-可见角色绑定" aria-label="Permalink to &quot;3.2 Agent 可见角色绑定&quot;">​</a></h2><p>受治理参与从 Agent 可见的显式角色绑定开始。绑定规定角色、协作上下文、任务范围、允许/禁止动作以及独立复核或升级角色。它是运行协议身份，不是密码学或法律身份。</p><h2 id="_3-3-生命周期" tabindex="-1">3.3 生命周期 <a class="header-anchor" href="#_3-3-生命周期" aria-label="Permalink to &quot;3.3 生命周期&quot;">​</a></h2><p>参考生命周期为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inbox → active → review → done → archive → history</span></span>
<span class="line"><span>           ↑        |</span></span>
<span class="line"><span>           └─ reject┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>动作</th><th>来源状态</th><th>目标状态</th><th>典型权限</th></tr></thead><tbody><tr><td><code>create_task</code></td><td>—</td><td><code>inbox</code></td><td>任务创建者</td></tr><tr><td><code>claim_task</code></td><td><code>inbox</code></td><td><code>active</code></td><td>被分配的执行者</td></tr><tr><td><code>submit_task</code></td><td><code>active</code></td><td><code>review</code></td><td>责任执行者</td></tr><tr><td><code>approve_task</code></td><td><code>review</code></td><td><code>done</code></td><td>复核者或批准者</td></tr><tr><td><code>reject_task</code></td><td><code>review</code></td><td><code>active</code></td><td>复核者</td></tr><tr><td><code>finish_task</code></td><td><code>active</code></td><td><code>done</code></td><td>Profile 授权角色</td></tr><tr><td><code>archive_task</code></td><td><code>done</code></td><td><code>archive</code></td><td>归档权限</td></tr><tr><td><code>archive_to_history</code></td><td><code>archive</code></td><td><code>history/...</code></td><td>归档权限</td></tr></tbody></table><p>路径表示当前 Profile 状态，迁移证据记录过程历史。路径与证据不一致时必须形成 ISSUE，而不是静默修复。</p><h2 id="_3-4-路由、原子发布与恢复" tabindex="-1">3.4 路由、原子发布与恢复 <a class="header-anchor" href="#_3-4-路由、原子发布与恢复" aria-label="Permalink to &quot;3.4 路由、原子发布与恢复&quot;">​</a></h2><p>参考文件名为 <code>{TYPE}-{YYYYMMDD}-{NNN}-{SENDER}-to-{RECIPIENT}(-slug).md</code>。文件名是传输封装；正文与 Schema 承载完整含义。在支持的平台上，原子发布通过先写临时文件再 Rename 实现。恢复从持久工件重建任务身份、当前生命周期、责任、关联证据、未解决依赖与问题，不依赖隐藏 Session 上下文。</p><h1 id="_4-codeflowmu-持久工作环境" tabindex="-1">4. CodeFlowMu 持久工作环境 <a class="header-anchor" href="#_4-codeflowmu-持久工作环境" aria-label="Permalink to &quot;4. CodeFlowMu 持久工作环境&quot;">​</a></h1><p>CodeFlowMu 研究跨 Session 持续存在的 AI 工作角色。模型和 Session 可以变化，但工作身份通过角色绑定、任务/Thread ID、报告和复核、批准/拒绝记录、生命周期迁移、未解决 ISSUE/依赖、恢复和归档证据继续存在。</p><p>这里的“数字员工”只表示能够接受委托工作、使用工具并跨 Session 提交证据的工程身份，不表示法律雇佣、人格、意识、人类意图，也不表示替代承担责任的人类或组织。</p><p>一项已观察 Session 展示了协议初始化与参与者身份的区别：FCoP 已初始化，但 Session 尚未分配角色；Agent 在制定开发计划前请求显式角色绑定，在获得 PM/共同复核者绑定后才确认角色并创建受治理规划工作。该观察只建立运行角色可见性，不建立密码学认证。</p><p>观察与测试路径包括 ADMIN/PM 委托、执行者 Claim 与执行、独立报告提交、QA/治理复核、批准/拒绝/等待人工状态、依赖等待与释放、ISSUE 创建、重启恢复和归档历史。当前限制是这些局部发现尚未被统一规范化为 TMPA 证据图与问题集合，因此 C13 仍为 PARTIAL。</p><p>当必需证据缺失、过期或不完整时，实现可以阻止 Release。CodeFlowMu 已保存足以证明部分重启与恢复行为的 Session、任务、报告、生命周期和 Ledger 证据，但尚无单一产品 Reader 把责任、生命周期、未解决依赖、冲突与问题重建为一个规范输出。</p><h1 id="_5-小典-ai-nl2sql-案例" tabindex="-1">5. 小典 AI NL2SQL 案例 <a class="header-anchor" href="#_5-小典-ai-nl2sql-案例" aria-label="Permalink to &quot;5. 小典 AI NL2SQL 案例&quot;">​</a></h1><p>公开演示位于 <code>https://demo.chedian.cc/</code>。产生数据的私有开发系统与公开仓库不被声称为同一个可直接复现构建。2026-07-29 快照显示 330 Profile、16,129 Event、924 Message、1,220 Index/Export、44 Knowledge 和 352 Audit 记录；这些是单次系统状态，不是性能基准。</p><p>NL2SQL 链覆盖授权、意图规范化、Schema/DDL 上下文、SQL 生成、只读验证、写入阻断、表白名单、租户隔离、字段/Join/枚举验证和结果合理性检查。一个车辆违法查询在 26,344 ms 后通过；一个车辆费用汇总查询在 131,994 ms 后被拒绝。价值在于保留通过与拒绝路径的分歧，而不是计算代表性通过率。</p><p>被拒绝链保留请求身份、验证阶段、明确结果、耗时、跨 Session 证据以及治理证据与生成 SQL 的分离。它演示真实应用能够保存治理相关记录、重建多阶段链、把拒绝保留为一等结果并展示策略门禁；它不证明完整 TMPA Core 一致性、代表性 SME 性能、独立采用、密码学不可抵赖性或每条记录的事实正确性。</p><h1 id="_6-公开-s0-4-c01–c14-语料库" tabindex="-1">6. 公开 S0.4 C01–C14 语料库 <a class="header-anchor" href="#_6-公开-s0-4-c01–c14-语料库" aria-label="Permalink to &quot;6. 公开 S0.4 C01–C14 语料库&quot;">​</a></h1><p>I0.3 曾描述本地 <code>tmpa-conformance.zip</code>，但该归档、Runner 与 Fixture 并未进入 GitHub 唯一事实源。I0.4 以公开仓库语料库 <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a> 取代不可用的交付声明；语料库 ID 为 <code>tmpa-s0.4-fcop-codeflowmu-20260803</code>。</p><p>语料库刻意分成两条证据轨道：</p><ol><li><strong>S0.4 Reference Reader 轨道。</strong> 只读实现消费合成 Fixture，验证公开 S0.4 Schema 与可执行 Profile，重建规范节点、边、问题、判断和视图，再核验 C01–C14 断言。</li><li><strong>锁定产品基线轨道。</strong> 机器可读断言把可取得的 FCoP、CodeFlowMu 与小典证据按更严格的 S0.4 标准重新裁决。Fixture PASS 绝不提升为产品 PASS。</li></ol><p>仓库命令为 <code>npm run tmpa:s0.4:conformance</code>。它在不修改产品仓库的前提下重新生成标准记录、Reference 与 Product 结果、执行日志、汇总和 SHA-256 文件 Manifest。Runner 对 S0.4 对象与 Reader Result Envelope 进行严格 JSON Schema 验证，并在求值前验证可执行的 Lifecycle/Type/Role/Relation Profile。</p><p>状态语义固定为：PASS 表示该轨道全部强制断言都已执行并匹配；PARTIAL 表示存在真实产品证据，但至少缺少一项 S0.4 必需观察或输出；NOT RUN 表示所需产品执行路径不可用；FAIL 表示已执行的强制断言不匹配。只有产品 C01–C14 全部 PASS 时，产品聚合结果才是 PASS。</p><p>FCoP <code>3.2.4</code> Commit <code>da79dfefd99f597c9e422ce9edec22157f915a21</code> 已直接取回，并在 Python 3.12.13 上重跑：<strong>1,137 项通过、2 项跳过、0 项失败</strong>。CodeFlowMu <code>V1.2.3</code> 锁定 Commit <code>8f342d028eb66e77d135bea58fdbc7f2d0627e3b</code> 无法从公开 <code>CodeFlowMu-open</code> 历史取回，因此 I0.4 将新的 CodeFlowMu 执行记录为 NOT RUN，只把 I0.3 保存的断言用于有边界的重新裁决。</p><table tabindex="0"><thead><tr><th>证据轨道</th><th style="text-align:right;">PASS</th><th style="text-align:right;">PARTIAL</th><th style="text-align:right;">NOT RUN</th><th style="text-align:right;">FAIL</th><th>聚合</th><th>声明级别</th></tr></thead><tbody><tr><td>S0.4 Reference Reader Fixture</td><td style="text-align:right;">14</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td style="text-align:right;">0</td><td>PASS</td><td>Implemented 且由作者 Demonstrated</td></tr><tr><td>FCoP–CodeFlowMu 产品基线</td><td style="text-align:right;">1</td><td style="text-align:right;">9</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td>PARTIAL</td><td>混合产品证据</td></tr></tbody></table><p>Reference Reader 结果表明已发布的解释可以执行。它<strong>不</strong>建立 FCoP、CodeFlowMu 或小典对 S0.4 的完整一致性，也不建立独立采用。</p>`,45))])}const S=o(i,[["render",s]]);export{P as __pageData,S as default};
